import artefact from "./calibration-elo-xp.json";

// The calibration artefact (amendment A7, contract §15). calibration-elo-xp.json is generated by
// docs/audits/calibration-elo-xp/make_artifact.py: never edited by hand and never recalculated here.
// Every edge keeps its bound, its uncertainty and whether it was admitted; only admitted edges decide anything.
export type EloEdge = "upper95" | "upper99" | "lower95" | "lower99";
export type XpEdge = "upper95" | "upper99";
export interface Edge { bound: number; uncertainty: number; admitted: boolean }
export interface Calibration {
  calibratedThrough: string;
  elo: { kMax: number; grid: number[]; edges: Partial<Record<EloEdge, Record<number, Edge>>> };
  xp: { grid: number[]; edges: Partial<Record<XpEdge, Record<number, Edge>>> }; // by window length in days
}

// The grids the method validated (design §4, §5). An artefact outside them is rejected, not interpreted.
export const ELO_GRID = [5, 10, 15, 20];
export const XP_GRID = [7, 14, 28];
const ELO_EDGES: EloEdge[] = ["upper95", "upper99", "lower95", "lower99"];
const XP_EDGES: XpEdge[] = ["upper95", "upper99"];

const fail = (m: string): never => { throw new Error(`calibration-elo-xp.json: ${m}`); };
const sameGrid = (a: unknown, g: number[]) => Array.isArray(a) && a.length === g.length && g.every((v, i) => a[i] === v);

function edges<E extends string>(names: E[], raw: any, admitted: any, grid: number[], where: string): Partial<Record<E, Record<number, Edge>>> {
  const out: Partial<Record<E, Record<number, Edge>>> = {};
  for (const e of names) {
    const adm: unknown[] = admitted?.[e] ?? fail(`${where}.admitted.${e} missing`);
    for (const k of adm) if (typeof k !== "number" || !grid.includes(k)) fail(`${where}.admitted.${e} has ${String(k)}, outside the validated grid ${grid}`);
    for (const [ks, v] of Object.entries<any>(raw?.[e] ?? fail(`${where}.edges.${e} missing`))) {
      const k = Number(ks);
      if (!grid.includes(k)) fail(`${where}.edges.${e} has ${ks}, outside the validated grid ${grid}`);
      if (!Number.isFinite(v?.bound) || !Number.isFinite(v?.uncertainty) || v.uncertainty < 0) fail(`${where}.${e}[${ks}] needs a numeric bound and a non-negative uncertainty`);
      (out[e] ??= {})[k] = { bound: v.bound, uncertainty: v.uncertainty, admitted: adm.includes(k) };
    }
    for (const k of adm) if (!out[e]?.[k as number]) fail(`${where}.admitted.${e} lists ${k}, which has no edge`);
  }
  return out;
}

export function parseCalibration(a: unknown): Calibration {
  const x = a as any;
  if (typeof x?.calibratedThrough !== "string" || !x.elo || !x.xp) fail("malformed");
  if (!sameGrid(x.elo.grid, ELO_GRID) || x.elo.kMax !== Math.max(...ELO_GRID)) fail(`elo grid must be ${ELO_GRID} with kMax ${Math.max(...ELO_GRID)}`);
  if (!sameGrid(x.xp.grid, XP_GRID)) fail(`xp grid must be ${XP_GRID}`);
  const elo = edges(ELO_EDGES, x.elo.edges, x.elo.admitted, ELO_GRID, "elo");
  const xp = edges(XP_EDGES, x.xp.edges, x.xp.admitted, XP_GRID, "xp");
  // coherence: "exceptional" is never less demanding than "relevant"; the band has a lower and an upper side
  for (const k of ELO_GRID) {
    const [u95, u99, l95, l99] = ELO_EDGES.map((e) => elo[e]?.[k]?.bound);
    if (u95 !== undefined && u99 !== undefined && u99 < u95) fail(`elo upper99 < upper95 at k=${k}`);
    if (l95 !== undefined && l99 !== undefined && l99 > l95) fail(`elo lower99 > lower95 at k=${k}`);
    if (u95 !== undefined && l95 !== undefined && !(l95 < u95)) fail(`elo lower95 >= upper95 at k=${k}`);
  }
  for (const w of XP_GRID) {
    const [q95, q99] = XP_EDGES.map((e) => xp[e]?.[w]?.bound);
    if (q95 !== undefined && q99 !== undefined && q99 < q95) fail(`xp upper99 < upper95 at window=${w}`);
  }
  return { calibratedThrough: x.calibratedThrough, elo: { kMax: x.elo.kMax, grid: ELO_GRID, edges: elo }, xp: { grid: XP_GRID, edges: xp } };
}

export const CALIBRATION: Calibration = parseCalibration(artefact);

export type Calibrated = { available: false } | { available: true; relevant: boolean; level: "relevant" | "exceptional" | null; lower: number | null; upper: number | null };

const adm = (m: Partial<Record<string, Record<number, Edge>>>, e: string, k: number) => { const x = m[e]?.[k]; return x?.admitted ? x.bound : undefined; };

// ELO: the band depends on k (games between the two anchors), exactly on the validated grid and never beyond kMax; each direction needs its own admitted edge.
export function eloVerdict(delta: number, k: number, cal: Calibration = CALIBRATION): Calibrated {
  const dir = delta >= 0 ? "upper" : "lower";
  const b95 = adm(cal.elo.edges, `${dir}95`, k);
  if (k > cal.elo.kMax || b95 === undefined) return { available: false };
  const b99 = adm(cal.elo.edges, `${dir}99`, k);
  const out = dir === "upper" ? delta > b95 : delta < b95;
  const exceptional = b99 !== undefined && (dir === "upper" ? delta > b99 : delta < b99);
  return { available: true, relevant: out, level: exceptional ? "exceptional" : out ? "relevant" : null, lower: dir === "lower" ? b95 : null, upper: dir === "upper" ? b95 : null };
}

// XP: one-sided (acceleration only), by exact window length.
export function xpVerdict(ratio: number, windowDays: number, cal: Calibration = CALIBRATION): Calibrated {
  const q95 = adm(cal.xp.edges, "upper95", windowDays);
  if (q95 === undefined) return { available: false };
  const q99 = adm(cal.xp.edges, "upper99", windowDays);
  const out = ratio > q95;
  return { available: true, relevant: out, level: q99 !== undefined && ratio > q99 ? "exceptional" : out ? "relevant" : null, lower: null, upper: q95 };
}

// Contract §15.2.5: the limits and the uncertainty of every edge of the rule's grid point, admitted or not, travel in `criteria`.
export function edgeCriteria(rule: "elo" | "xp", point: number | null, cal: Calibration): Record<string, number | string> {
  const out: Record<string, number | string> = { calibratedThrough: cal.calibratedThrough };
  if (point === null) return out;
  const table = rule === "elo" ? cal.elo.edges : cal.xp.edges;
  for (const [name, byPoint] of Object.entries<Record<number, Edge> | undefined>(table)) {
    const e = byPoint?.[point];
    if (e) { out[name] = e.bound; out[`${name}Uncertainty`] = e.uncertainty; out[`${name}Admitted`] = e.admitted ? 1 : 0; }
  }
  return out;
}
